// ✅ ISP Names to block
export const blockedISPs = [
  'amazon',
  'aws',
  'google',
  'microsoft',
  'azure',
  'digitalocean',
  'vultr',
  'linode',
  'oracle',
  'ovh',
  'hetzner',
  'cloudflare',
  'fastly',
  'akamai',
  'Datacamp Limited',
];

// Helper for CIDR checking
const ipToInt = (ip) => {
  return ip.split('.').reduce((acc, octet) => (acc << 8) + parseInt(octet, 10), 0) >>> 0;
};

const isIPInCIDR = (ip, cidr) => {
  const [network, maskBits] = cidr.split('/');
  const mask = ~((1 << (32 - parseInt(maskBits))) - 1) >>> 0;
  const ipInt = ipToInt(ip);
  const networkInt = ipToInt(network);
  return (ipInt & mask) === (networkInt & mask);
};

// ✅ Function to check if ISP is blocked
export const isISPBlocked = (isp) => {
  if (!isp) return false;
  const lowerISP = isp.toLowerCase();
  return blockedISPs.some(blocked => lowerISP.includes(blocked));
};

// ✅ Function to add ISP to blocked list
export const addBlockedISP = (isp) => {
  if (!blockedISPs.includes(isp.toLowerCase())) {
    blockedISPs.push(isp.toLowerCase());
    return true;
  }
  return false;
};

// ✅ Function to get all blocked ISPs
export const getBlockedISPs = () => {
  return [...blockedISPs];
};

// Function to check if an IP is blocked
export const isIPBlocked = (ip) => {
  if (!ip) return false;
  
  // Check exact matches
  if (exactBlockedIPs.includes(ip)) {
    return true;
  }
  
  // Check CIDR ranges
  for (const cidr of blockedCIDRs) {
    if (isIPInCIDR(ip, cidr)) {
      return true;
    }
  }
  
  // Check patterns
  for (const pattern of blockedIPPatterns) {
    try {
      const regex = new RegExp(pattern);
      if (regex.test(ip)) {
        return true;
      }
    } catch (e) {
      console.error('Invalid regex pattern:', pattern);
    }
  }
  
  return false;
};

// Function to add IP to blocked list
export const addBlockedIP = (ip) => {
  if (!exactBlockedIPs.includes(ip)) {
    exactBlockedIPs.push(ip);
    return true;
  }
  return false;
};

// Function to remove IP from blocked list
export const removeBlockedIP = (ip) => {
  const index = exactBlockedIPs.indexOf(ip);
  if (index > -1) {
    exactBlockedIPs.splice(index, 1);
    return true;
  }
  return false;
};

// Function to get all blocked IPs
export const getBlockedIPs = () => {
  return [...exactBlockedIPs];
};

export default exactBlockedIPs;

